// Pentago (Declarative). Two players on a 6x6 board of four 3x3 quadrants
// (0 top-left, 1 top-right, 2 bottom-left, 3 bottom-right). A move places the
// mover's marble on an empty cell and then rotates one quadrant a quarter
// turn; the rotation is mandatory and part of the same move. Five in a row
// wins: checked after the placement (a placement five wins for the mover
// regardless of the rotation) and again after the rotation (only the mover
// has five: the mover wins; only the opponent: the opponent wins; both: the
// player who rotated wins). A full board with no five is a draw.
const LINES = [];
for (let r = 0; r < 6; r++) for (let c = 0; c < 6; c++)
  for (const [dr, dc] of [[0, 1], [1, 0], [1, 1], [1, -1]]) {
    const er = r + 4 * dr, ec = c + 4 * dc;
    if (er < 0 || er > 5 || ec < 0 || ec > 5) continue;
    const line = [];
    for (let i = 0; i < 5; i++) line.push((r + i * dr) * 6 + c + i * dc);
    LINES.push(line);
  }
function hasFive(board, seat) {
  return LINES.some(line => line.every(cell => board[cell] === seat));
}
function quadDest(cell, quadrant, dir) {
  const r0 = quadrant >= 2 ? 3 : 0, c0 = quadrant % 2 ? 3 : 0;
  const r = Math.floor(cell / 6) - r0, c = cell % 6 - c0;
  const tr = dir === 1 ? c : 2 - c, tc = dir === 1 ? 2 - r : r;
  return (r0 + tr) * 6 + c0 + tc;
}
function rotateArray(values, quadrant, dir) {
  const r0 = quadrant >= 2 ? 3 : 0, c0 = quadrant % 2 ? 3 : 0;
  const before = [];
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++)
    before.push(values[(r0 + r) * 6 + c0 + c]);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++)
    values[quadDest((r0 + r) * 6 + c0 + c, quadrant, dir)] = before[r * 3 + c];
}
function rotateQuadrant(board, quadrant, dir) {
  rotateArray(board, quadrant, dir);
}
function legalMoves(s) {
  if (s.over) return [];
  const out = [];
  for (let cell = 0; cell < 36; cell++) if (s.board[cell] === -1)
    for (let quadrant = 0; quadrant < 4; quadrant++)
      for (const dir of [1, -1]) out.push({type: 'place', cell, quadrant, dir});
  return out;
}
function rotatedCopy(board, move, seat) {
  const b = board.slice();
  b[move.cell] = seat;
  rotateQuadrant(b, move.quadrant, move.dir);
  return b;
}
function payoutsFor(s, ctx) {
  const humans = ctx.players.filter(p => p.kind === 'human' && p.active !== false);
  const out = {};
  if (!humans.length) return out;
  const winner = s.winner >= 0 ? ctx.players[s.winner] : null;
  const winnerPaid = winner && winner.kind === 'human' && winner.active !== false;
  humans.forEach(p => { out[p.id] = 0; });
  if (winnerPaid) { out[winner.id] = ctx.pot; return out; }
  humans.forEach((p, i) => {
    out[p.id] = Math.floor(ctx.pot / humans.length) + (i < ctx.pot % humans.length ? 1 : 0);
  });
  return out;
}
function evaluateMove(s, move) {
  // Returns the board after place+rotate and the winner (-2 = game continues).
  const seat = s.turn, b = s.board.slice();
  b[move.cell] = seat;
  const placedFive = hasFive(b, seat);
  rotateQuadrant(b, move.quadrant, move.dir);
  let winner = -2;
  if (placedFive) winner = seat;
  else if (hasFive(b, seat)) winner = seat;
  else if (hasFive(b, 1 - seat)) winner = 1 - seat;
  else if (b.every(v => v !== -1)) winner = -1;
  return {board: b, winner};
}
const game = {
  newMatch(ctx) {
    const s = {board: Array(36).fill(-1), turn: 0, winner: -1, turns: 0, over: false,
      ids: Array(36).fill(null), last_move: null};
    return {state: s, turn: [ctx.players[0].id]};
  },
  applyMove(state, id, move, ctx) {
    if (state.over || ctx.players[state.turn].id !== id || !move ||
        typeof move !== 'object' || Array.isArray(move))
      throw new InvalidMove('Illegal move');
    const options = legalMoves(state), keys = Object.keys(move);
    if (!options.some(m => Object.keys(m).length === keys.length &&
        keys.every(k => Object.prototype.hasOwnProperty.call(m, k) && m[k] === move[k])))
      throw new InvalidMove('Illegal move');
    const s = JSON.parse(JSON.stringify(state));
    // Stable marble identity: the n-th marble a seat places is 'm_<seat>_<n>'
    // for its whole life; ids rotate together with the board so a marble
    // keeps its ID wherever a quadrant rotation carries it.
    const seat = s.turn;
    const placedId = 'm_' + seat + '_' + s.board.filter(v => v === seat).length;
    const idsAfter = (Array.isArray(s.ids) ? s.ids : Array(36).fill(null)).slice();
    idsAfter[move.cell] = placedId;
    const rotated = [];
    {
      const r0 = move.quadrant >= 2 ? 3 : 0, c0 = move.quadrant % 2 ? 3 : 0;
      for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
        const from = (r0 + r) * 6 + c0 + c, to = quadDest(from, move.quadrant, move.dir);
        if (idsAfter[from] !== null && to !== from)
          rotated.push({piece_id: idsAfter[from], from, to});
      }
    }
    rotateArray(idsAfter, move.quadrant, move.dir);
    s.ids = idsAfter;
    s.last_move = {kind: 'place_rotate', placed_piece_id: placedId,
      placed_cell: move.cell, quadrant: move.quadrant, direction: move.dir,
      rotated};
    const result = evaluateMove(s, move);
    s.board = result.board;
    s.turns++;
    if (result.winner !== -2) {
      s.over = true;
      s.winner = result.winner;
      return {state: s, turn: null, payouts: payoutsFor(s, ctx)};
    }
    s.turn = 1 - s.turn;
    return {state: s, turn: [ctx.players[s.turn].id]};
  },
  viewFor(state, id, ctx) {
    const s = JSON.parse(JSON.stringify(state));
    s.legal = id === ctx.players[state.turn].id && !state.over ? legalMoves(state) : [];
    return s;
  },
  randomMove(s, id, ctx) {
    const options = legalMoves(s);
    return options[Math.floor(ctx.random() * options.length)];
  },
  computerMove(s, id, ctx) {
    const options = legalMoves(s);
    const seat = s.turn;
    // Cells where the opponent would complete five by placing there: taking
    // one of them (or rotating it away) is the simple blocking heuristic.
    let best = options[0], bestScore = -Infinity;
    const threatCells = new Set();
    const probe = s.board.slice();
    for (let cell = 0; cell < 36; cell++) if (probe[cell] === -1) {
      probe[cell] = 1 - seat;
      if (hasFive(probe, 1 - seat)) threatCells.add(cell);
      probe[cell] = -1;
    }
    for (const move of options) {
      const result = evaluateMove(s, move);
      let score = 0;
      if (result.winner === seat) score += 10000;
      else if (result.winner === 1 - seat) score -= 10000;
      else if (result.winner === -1) score += 5;
      const b = result.board;
      for (const line of LINES) {
        let mine = 0, theirs = 0, empty = 0;
        for (const cell of line) {
          if (b[cell] === seat) mine++;
          else if (b[cell] === 1 - seat) theirs++;
          else empty++;
        }
        if (theirs === 0) score += mine * mine * 3;
        if (mine === 0) score -= theirs * theirs * 2;
        if (theirs === 4 && empty === 1) score -= 400;
        if (mine === 4 && empty === 1) score += 300;
      }
      // Block an immediate placement five: occupy the opponent's fifth cell.
      if (threatCells.has(move.cell)) score += 500;
      const r = Math.floor(move.cell / 6), c = move.cell % 6;
      score += 6 - (Math.abs(r - 2.5) + Math.abs(c - 2.5));
      if (score > bestScore) { bestScore = score; best = move; }
    }
    return best;
  }
};

