const SOURCE_STRINGS = {"title": "Pentago", "turn": "Player {n}", "finished": "Finished", "winner": "Player {n} wins", "draw": "Draw", "hint_place": "Tap an empty cell to place your marble", "hint_rotate": "Tap a button to rotate a quadrant", "cell": "Cell {n}", "rotate_cw": "Rotate quadrant {q} clockwise", "rotate_ccw": "Rotate quadrant {q} counterclockwise", "server_invalid": "Illegal move"};
// Pentago presentation. Pure JSON in, JSON scene out. The board is four 3x3
// grid boards (q0 top-left, q1 top-right, q2 bottom-left, q3 bottom-right)
// with a visible gap between quadrants. Two taps make one move: tap an
// empty cell to select the placement, then tap one of the eight rotation
// buttons; that second tap emits the single {type:'place',...} move.
const gameUI = {
  reduce(message, localState) {
    const m = message.type === 'ui_event' ? message.state_changed : message;
    const s = m.view || m.state;
    const strings = Object.assign({}, SOURCE_STRINGS, m.strings || {});
    const t = (key, args = {}) => (strings[key] || key).replace(/\{(\w+)\}/g,
      (_, k) => String(args[k] === undefined ? '' : args[k]));
    const over = m.status === 'over' || s.over;
    const active = !over && !m.replay && m.acting_for_player_index !== null &&
      m.acting_for_player_index !== undefined;
    const legal = active ? (s.legal || []) : [];
    const quadrantOf = cell => (Math.floor(cell / 6) >= 3 ? 2 : 0) + (cell % 6 >= 3 ? 1 : 0);
    const localOf = cell => (Math.floor(cell / 6) % 3) * 3 + (cell % 6) % 3;
    // Keep the selected placement only within the same move and actor.
    let selected = null;
    if (active && localState && localState.moveCount === m.move_count &&
        localState.actor === m.acting_for_player_index &&
        Number.isInteger(localState.selected) &&
        legal.some(move => move.cell === localState.selected))
      selected = localState.selected;
    if (message.type === 'ui_event' && active && message.event.type === 'tap') {
      const id = message.event.id || '';
      const cellMatch = /^cell_(\d+)$/.exec(id);
      if (cellMatch && legal.some(move => move.cell === Number(cellMatch[1])))
        selected = Number(cellMatch[1]);
    }
    const pieces = [], targets = [], controls = [];
    const status = over
      ? (s.winner >= 0 ? t('winner', {n: s.winner + 1}) : t('draw'))
      : t('turn', {n: s.turn + 1});
    const labels = [
      {id: 'title', text: t('title'), x: 24, y: 18, font_size: 26},
      {id: 'turn', text: status, x: 24, y: 54, font_size: 18}
    ];
    if (active) labels.push({id: 'hint',
      text: selected === null ? t('hint_place') : t('hint_rotate'),
      x: 200, y: 54, font_size: 15});
    const move = s.last_move;
    for (let q=0;q<4;q++)
      pieces.push({id:'plate_'+q,type:'plate',board:'q'+q,position:{x:100,y:100},actions:[]});
    function offset(cell) {
      const slot=localOf(cell);
      return {x:(slot%3-1)*200/3,y:(Math.floor(slot/3)-1)*200/3};
    }
    s.board.forEach((value, cell) => {
      if (value === -1) return;
      pieces.push({id: (s.ids && s.ids[cell]) || 'piece_' + cell, type: 'p' + value, board: 'q' + quadrantOf(cell),
        parent:"plate_"+quadrantOf(cell), position:offset(cell), actions: []});
    });
    if (selected !== null) pieces.push({id: 'pending', type: 'p' + s.turn,
      board: 'q' + quadrantOf(selected), position: {cell: String(localOf(selected))},
      opacity: 0.55, selected: true, actions: []});
    if (active) {
      const cells = [...new Set(legal.map(move => move.cell))].sort((a, b) => a - b);
      for (const cell of cells) targets.push({id: 'cell_' + cell,
        board: 'q' + quadrantOf(cell), position: {cell: String(localOf(cell))},
        label: t('cell', {n: cell + 1}), aria_label: t('cell', {n: cell + 1})});
      if (selected !== null) for (let q = 0; q < 4; q++) for (const dir of [1, -1])
        controls.push({id: 'rot_' + q + '_' + dir, kind: 'button',
          label: t(dir === 1 ? 'rotate_cw' : 'rotate_ccw', {q: q + 1})});
    }
    const scene = {pieces, targets, controls, labels};
    const out = {scene, local_state: {
      moveCount: m.move_count === undefined ? null : m.move_count,
      actor: active ? m.acting_for_player_index : null, selected}};
    if (message.type === 'ui_event' && active && selected !== null &&
        message.event.type === 'tap') {
      const rot = /^rot_(\d+)_(-?1)$/.exec(message.event.id || '');
      if (rot) {
        const move = {type: 'place', cell: selected,
          quadrant: Number(rot[1]), dir: Number(rot[2])};
        if (legal.some(option => option.type === move.type && option.cell === move.cell &&
            option.quadrant === move.quadrant && option.dir === move.dir))
          out.make_move = move;
      }
    }
    if (message.type==='state_changed' && move && move.kind==='place_rotate') {
      const finalCell=s.ids.indexOf(move.placed_piece_id);
      if (finalCell>=0) {
        // During the drop the plate is still at its previous angle.
        // Convert the entry point into the final plate's local coordinates.
        const point=offset(move.placed_cell);
        const turned=quadrantOf(finalCell)===move.quadrant;
        const from=turned ? {x:move.direction*128,y:move.direction*point.x} : {x:point.x,y:-128};
        out.timeline={key:'place_'+move.placed_piece_id,steps:[
          [{piece_id:move.placed_piece_id,from:{position:from},duration_ms:500}],
          [{piece_id:'plate_'+move.quadrant,from:{rotation:-90*move.direction},duration_ms:600}]
        ]};
      }
    }
    return out;
  }
};
